package node

import (
	"bytes"
	"io"

	"github.com/jpl-au/fluent"
)

// FunctionComponent enables dynamic content generation through function calls.
// The function is called during rendering to generate the actual node content.
// This is useful for complex conditional logic, loops, and data transformations.
//
// Nil nodes are safely ignored - if the function returns nil, nothing will be rendered.
//
// Chain .Dynamic("key") to enable diff engine tracking. Without a key, the
// differ cannot produce targeted patches for content generated by the function.
//
// Usage:
//
//	node.Func(func() Node {
//	    if user.IsLoggedIn {
//	        return div.Text("Welcome back!")
//	    }
//	    return div.Text("Please log in")
//	}).Dynamic("greeting")
type FunctionComponent struct {
	fn      func() Node
	dynamic string
}

// Func creates a new function component that will call the provided function
// during rendering to generate the actual node content.
//
// The function may be evaluated more than once per render cycle:
// rendering evaluates it, and any tree walk (validation, a custom
// walker calling Nodes) evaluates it again. Write functions that are
// cheap, deterministic and side-effect free - in particular, ranging
// over a map produces a different order on every evaluation; sort the
// keys first. The jit engines guarantee exactly one evaluation per
// render as an optimisation, but code must stay correct without that
// guarantee.
func Func(fn func() Node) *FunctionComponent {
	return &FunctionComponent{
		fn: fn,
	}
}

// Render calls the function and writes its rendered output to w.
// Write errors are intentionally discarded; see [Node] for rationale.
func (f *FunctionComponent) Render(w io.Writer) {
	_, _ = f.WriteTo(w)
}

// WriteTo calls the function and writes its rendered output to w,
// returning the byte count and any write error. Satisfies [io.WriterTo].
func (f *FunctionComponent) WriteTo(w io.Writer) (int64, error) {
	buf := fluent.NewBuffer()
	f.RenderBuilder(buf)
	n, err := buf.WriteTo(w)
	fluent.PutBuffer(buf)
	return n, err
}

// RenderBytes calls the function and returns its rendered output as a
// byte slice.
func (f *FunctionComponent) RenderBytes() []byte {
	var buf bytes.Buffer
	f.RenderBuilder(&buf)
	return buf.Bytes()
}

// RenderBuilder writes the HTML representation directly to a buffer.
// Calls the function to get the actual node and renders it.
// Nil nodes are safely ignored.
func (f *FunctionComponent) RenderBuilder(buf *bytes.Buffer) {
	if f.fn != nil {
		node := f.fn()
		if node != nil {
			node.RenderBuilder(buf)
		}
	}
}

// IsDynamic returns true - function components always contain dynamic content
// because their output depends on a function call at render time.
func (f *FunctionComponent) IsDynamic() bool {
	return true
}

// Dynamic marks this function component for reactive tracking by the diff engine.
// The key identifies this node across renders so the diff engine can detect
// changes and send targeted patches.
func (f *FunctionComponent) Dynamic(key string) *FunctionComponent {
	f.dynamic = key
	return f
}

// DynamicKey returns the developer-assigned key for diff engine tracking.
// Returns an empty string if the component has not been marked as dynamic.
func (f *FunctionComponent) DynamicKey() string {
	return f.dynamic
}

// Nodes evaluates the function and returns its output. Returning an empty
// slice would hide any keyed children from tree walkers, which breaks the
// Differ's ability to detect patches and structural changes for elements
// generated by function components.
//
// Because Nodes evaluates the function, a walker sees a fresh
// evaluation - not the content a previous render produced. Walkers
// that need render/walk coherence must render and walk in a single
// pass, the way the jit Differ does.
func (f *FunctionComponent) Nodes() []Node {
	if f.fn != nil {
		if n := f.fn(); n != nil {
			return []Node{n}
		}
	}
	return nil
}
